// 토리 영어 안내 — js/tori.js TOPICS와 같은 순서(주제별 단계 번호)로 말풍선(say) · 녹음 문장(voice)을 둔다
// 단계 수가 다르면 tori.js가 그 주제는 한국어로 둔다 (tests/toriEn.mjs가 맞는지 확인)
// 실시간 수치가 들어가는 단계는 say(T, H) — H는 tori.js의 공장 상태 도우미 (fos · adv · ex · qx …)
//   시뮬레이터가 만든 한국어 글(제안 제목 · 셀 이름 · 작업 이름)은 넣지 않고 ID · 수치만 쓴다
import { LEVERS } from './impact.js';

const sec = (s) => `${Math.max(0, s).toFixed(1)}s`;
const at = (T, x) => `+${sec(x.t - T.ev.t0)}`;
const took = (T) => { const d = T.ev.tDetect - (T.ev.tq ?? T.ev.t0); return d < 0.5 ? 'immediately' : `in ${sec(d)}`; };
const UNIT = { '초': 's', '개': ' pcs', '대': ' units' };
const levV = (p, v) => { const L = LEVERS[p.lever]; return L ? `${Number.isInteger(v) ? v : (+v).toFixed(2)}${UNIT[L.unit] ?? L.unit}` : `${v}`; };
const LEVER = { pmThreshold: 'PM start health', alarmDelay: 'failure call delay', orchLatency: 'incident decision delay', reorderPoint: 'material reorder point', releaseMargin: 'release interval factor', releaseInterval: 'release interval', amrStage: 'AMR pre-dispatch', ecoWait: 'cell eco-mode wait', cpkMin: 'recalibration Cpk' };
const LOSS = { failure: 'equipment failure', pm: 'predictive maintenance', cal: 'recalibration', parts: 'parts shortage', supply: 'supply disruption', hazard: 'field event on route', command: 'stop · slow command', flow: 'flow · balance wait', ship: 'shipping space wait', speed: 'cycle speed loss', quality: 'quality defects' };
const REC = { apply: 'apply recommended', neutral: 'little effect', hold: 'hold recommended' };
const DEC = { policy: 'policy approval', 'due-risk': 'due-date risk', timeout: 'response timeout', 'first-article': 'first-article fail', 'tool-stock': 'tool stock', 'machine-pm': 'spindle predictive maintenance', 'insp-priority': 'inspection priority', 'maint-support': 'maintenance support' };
const EVT = { leak: 'oil leak on the floor', debris: 'debris on the floor', intrusion: 'unauthorized entry into a safety zone', smoke: 'suspected smoke' };
const LOT = { hold: 'shipment on hold · awaiting verdict', released: 'passed · hold released', contain: 'failed · contained', sorting: 'contained · sorting', done: 'sorted · dispositioned' };
const PROD = { doortrim: 'door trim', eaxle: 'e-axle', hood: 'hood', door: 'door', hblock: 'hydraulic block', rcover: 'rear cover' };
const prod = (p) => PROD[p] ?? p;
// 로봇 · 트럭 이름(시뮬레이터가 한국어로 지음: 휴머노이드-정비2 · 순찰 드론-1 …) → 영어
const WORD = [['순찰 드론', 'Patrol drone'], ['휴머노이드', 'Humanoid'], ['사족보행', 'Quadruped'], ['정밀검사', 'Inspection'], ['협동로봇', 'Cobot'], ['6축로봇', '6-axis robot'], ['입고트럭', 'Inbound truck'], ['화물트럭', 'Truck'],
  ['정비원', 'Technician'], ['작업자', 'Worker'], ['지게차', 'Forklift'], ['갠트리', 'Gantry'], ['드론', 'Drone'], ['정비', 'Maint'], ['물류', 'Logistics'], ['보충', 'Supply'], ['부품', 'Parts'], ['트럭', 'Truck']];
const nm = (id) => WORD.reduce((a, [k, e]) => a.replaceAll(k, e), String(id ?? ''));

